Sure! Below is a GO function that reads a number from the user and outputs the square root of that number. The function uses the `math.Sqrt` function from the `math` package to calculate the square root.

```go
package main

import (
	"fmt"
	"math"
)

func main() {
	// Declare a variable to hold the user input
	var number float64

	// Prompt the user to enter a number
	fmt.Print("Enter a number: ")
	_, err := fmt.Scanf("%f", &number)
	if err != nil {
		fmt.Println("Error reading input:", err)
		return
	}

	// Calculate the square root of the number
	squareRoot := math.Sqrt(number)

	// Output the square root
	fmt.Printf("The square root of %.2f is %.2f\n", number, squareRoot)
}
```

